data class Reader(val id: String)

sealed interface RowResult {
    data class Ok(val reader: Reader) : RowResult
    data class Invalid(val line: Int, val reason: String) : RowResult
}

fun label(result: RowResult): String = when (result) {
    is RowResult.Ok -> "ok"
    is RowResult.Invalid -> "bad"
}

data class Reader(val id: String, val location: String, val battery: Int)

sealed interface RowResult {
    data class Ok(val reader: Reader) : RowResult
    data class Invalid(val line: Int, val reason: String) : RowResult
}

fun parseReader(lineNo: Int, row: String): RowResult {
    val cols = row.split(",").map { it.trim() }
    if (cols.size != 3) return RowResult.Invalid(lineNo, "expected 3 columns, got ${cols.size}")
    val (id, location, batteryText) = cols
    if (id.isEmpty()) return RowResult.Invalid(lineNo, "missing reader id")
    val battery = batteryText.toIntOrNull()
        ?: return RowResult.Invalid(lineNo, "battery is not a number")
    if (battery !in 0..100) return RowResult.Invalid(lineNo, "battery out of range: $battery")
    return RowResult.Ok(Reader(id, location, battery))
}

fun describe(result: RowResult): String = when (result) {
    is RowResult.Ok -> "ok ${result.reader.id}"
    is RowResult.Invalid -> "line ${result.line}: ${result.reason}"
}

fun main() {
    println(describe(parseReader(2, "r-7, Toronto, 80")))
    println(describe(parseReader(3, "r-8, Montreal, 101")))
}

