class MovingAverage(private val size: Int) {
    private val values = ArrayDeque<Int>()
    private var sum = 0L

    fun add(value: Int): Double {
        values.addLast(value)
        sum += value
        if (values.size > size) sum -= values.removeFirst()
        return sum.toDouble() / values.size
    }
}

fun main() {
