data class Edge(val to: String, val cost: Int)

fun cheapest(graph: Map<String, List<Edge>>, start: String, goal: String): Int? {
    val best = mutableMapOf(start to 0)
    val queue = java.util.PriorityQueue<Pair<Int, String>>(compareBy { it.first })
    queue.add(0 to start)
    while (queue.isNotEmpty()) {
        val (cost, node) = queue.poll()
        if (node == goal) return cost
        if (cost > best.getValue(node)) continue
        for (edge in graph[node].orEmpty()) {
            val next = cost + edge.cost
            if (next < (best[edge.to] ?: Int.MAX_VALUE)) {
                best[edge.to] = next
                queue.add(next to edge.to)
            }
        }
    }
    return null
}

fun main() {
    val graph = mapOf(
        "US" to listOf(Edge("CA", 3), Edge("GB", 8)),
        "GB" to listOf(Edge("CA", 2))
    )
    println(cheapest(graph, "US", "CA"))
}

