data class PathResult(val cost: Int, val path: List<String>)

fun cheapestPath(spec: String, start: String, goal: String): PathResult? {
    val graph = mutableMapOf<String, MutableList<Pair<String, Int>>>()
    for (part in spec.split(",").filter { it.isNotBlank() }) {
        val (from, to, costText) = part.split(":")
        graph.getOrPut(from) { mutableListOf() }.add(to to costText.toInt())
    }
    val best = mutableMapOf(start to 0)
    val previous = mutableMapOf<String, String?>()
    val queue = java.util.PriorityQueue<Pair<Int, String>>(compareBy { it.first })
    queue.add(0 to start)
    while (queue.isNotEmpty()) {
        val (cost, node) = queue.poll()
        if (cost > best.getValue(node)) continue
        if (node == goal) {
            val path = generateSequence(goal) { previous[it] }.toList().reversed()
            return PathResult(cost, path)
        }
        for ((next, edgeCost) in graph[node].orEmpty()) {
            val nextCost = cost + edgeCost
            if (nextCost < (best[next] ?: Int.MAX_VALUE)) {
                best[next] = nextCost
                previous[next] = node
                queue.add(nextCost to next)
            }
        }
    }
    return null
}

