class Heartbeat(private val clock: Clock, private val intervalMillis: Long) {
    private var lastSent: Long? = null

    fun shouldSend(): Boolean {
        val now = clock.nowMillis()
        val last = lastSent
        if (last != null && now - last < intervalMillis) return false
        lastSent = now
        return true
    }
}

fun expect(name: String, expected: Boolean, actual: Boolean) {
