enum class SendResult { SUCCESS, RETRYABLE, PERMANENT }

fun interface Uploader {
    fun upload(batch: List<String>): SendResult
}

fun retryUpload(uploader: Uploader, batch: List<String>, maxAttempts: Int): SendResult {
    require(maxAttempts > 0)
    repeat(maxAttempts - 1) {
        when (val result = uploader.upload(batch)) {
            SendResult.SUCCESS, SendResult.PERMANENT -> return result
            SendResult.RETRYABLE -> Unit
        }
    }
    return uploader.upload(batch)
}

