fun interface Clock { fun nowMillis(): Long }

class FakeClock(var now: Long = 0) : Clock {
    override fun nowMillis() = now
}

class TtlCache(private val clock: Clock, private val ttlMillis: Long) {
    private var entry: Pair<String, Long>? = null

    fun put(value: String) {
        entry = value to clock.nowMillis()
    }

    fun get(): String? {
        val current = entry ?: return null
        return if (clock.nowMillis() - current.second < ttlMillis) current.first else null
    }
}

fun main() {
    val clock = FakeClock(0)
    val cache = TtlCache(clock, 1_000)
    cache.put("ready")
    println(cache.get())
    clock.now = 1_000
    println(cache.get())
}

