data class StoredEvent(val value: String, val addedAt: Long)
fun interface Clock { fun nowMillis(): Long }
fun interface TelemetryUploader { fun upload(events: List<StoredEvent>): Boolean }

class TelemetryBatcher(
    private val batchSize: Int,
    private val maxAgeMillis: Long = Long.MAX_VALUE,
    private val capacity: Int = Int.MAX_VALUE,
    private val clock: Clock = Clock { 0L }
) {
    private val events = ArrayDeque<StoredEvent>()
    private val droppedEvents = mutableListOf<StoredEvent>()
    private var online = true
    fun add(value: String): List<StoredEvent> {
        events.addLast(StoredEvent(value, clock.nowMillis()))
        while (events.size > capacity) droppedEvents += events.removeFirst()
        return if (online && events.size >= batchSize) events.take(batchSize) else emptyList()
    }
    fun check(): List<StoredEvent> {
        val first = events.firstOrNull() ?: return emptyList()
        return if (online && clock.nowMillis() - first.addedAt >= maxAgeMillis) events.take(batchSize) else emptyList()
    }
    fun upload(uploader: TelemetryUploader): List<StoredEvent> {
        if (!online || events.isEmpty()) return emptyList()
        val batch = events.take(batchSize)
        if (!uploader.upload(batch)) return emptyList()
        repeat(batch.size) { events.removeFirst() }
        return batch
    }
    fun stored(): List<StoredEvent> = events.toList()
    fun dropped(): List<StoredEvent> = droppedEvents.toList()
    fun setOnline(online: Boolean) { this.online = online }
}

