data class AppVersion(val major: Int, val minor: Int, val patch: Int)
sealed interface FeatureResult {
    data object Enabled : FeatureResult
    data object TooOld : FeatureResult
    data object InvalidVersion : FeatureResult
    data object DisabledByRollout : FeatureResult
}
private fun parseVersion(text: String): AppVersion? = try {
    val parts = text.split('.')
    if (parts.size != 3 || parts.any { it.isEmpty() || it.any { ch -> !ch.isDigit() } }) null
    else AppVersion(parts[0].toInt(), parts[1].toInt(), parts[2].toInt())
} catch (e: NumberFormatException) { null }
fun compareVersions(left: String, right: String): Int {
    val a = requireNotNull(parseVersion(left)); val b = requireNotNull(parseVersion(right))
    return compareValuesBy(a, b, { it.major }, { it.minor }, { it.patch })
}
fun gateVersion(version: String, minimum: String): FeatureResult {
    val actual = parseVersion(version) ?: return FeatureResult.InvalidVersion
    val required = parseVersion(minimum) ?: return FeatureResult.InvalidVersion
    return if (compareValuesBy(actual, required, { it.major }, { it.minor }, { it.patch }) >= 0) FeatureResult.Enabled else FeatureResult.TooOld
}
fun rolloutVersion(version: String, minimum: String, installId: String, percentage: Int): FeatureResult {
    if (gateVersion(version, minimum) != FeatureResult.Enabled) return gateVersion(version, minimum)
    val bucket = installId.sumOf { it.code } % 100
    return if (bucket < percentage) FeatureResult.Enabled else FeatureResult.DisabledByRollout
}

