data class InvalidReaderEvent(val index: Int, val event: String, val state: ReaderState)
data class ReaderRun(val finalState: ReaderState, val invalidEvents: List<InvalidReaderEvent>, val successfulPayments: Int, val reconciliationCount: Int)
data class ReaderSummary(val state: ReaderState, val successfulPayments: Int, val reconciliationCount: Int = 0)
fun nextState(state: ReaderState, event: String): ReaderState? = when {
    state == ReaderState.DISCONNECTED && event == "connect" -> ReaderState.CONNECTED
    state == ReaderState.CONNECTED && event == "collect" -> ReaderState.COLLECTING
    state == ReaderState.COLLECTING && event == "card_presented" -> ReaderState.PROCESSING
    state == ReaderState.COLLECTING && event == "cancel" -> ReaderState.CONNECTED
    state == ReaderState.PROCESSING && event == "succeeded" -> ReaderState.CONNECTED
    state == ReaderState.PROCESSING && event == "failed" -> ReaderState.COLLECTING
    state != ReaderState.DISCONNECTED && event == "disconnect" -> ReaderState.DISCONNECTED
    else -> null
}
fun runReader(events: List<String>): ReaderRun {
    var state = ReaderState.DISCONNECTED; val invalid = mutableListOf<InvalidReaderEvent>(); var successes = 0; var reconciliations = 0
    events.forEachIndexed { index, event -> val old = state; val next = nextState(old, event); if (next == null) invalid += InvalidReaderEvent(index, event, old) else { if (old == ReaderState.PROCESSING && event == "succeeded") successes++; ____1; state = next } }
    return ReaderRun(state, invalid, successes, reconciliations)
}
fun runManyReaders(input: String): Map<String, ReaderSummary> {
    val states = linkedMapOf<String, ReaderState>(); val successes = mutableMapOf<String, Int>(); val reconciliations = mutableMapOf<String, Int>()
    for (line in input.lines()) {
        if (line.isBlank()) continue
        ____3
        val id = parts[0]; val event = parts[1]; val old = states[id] ?: ReaderState.DISCONNECTED; val next = nextState(old, event) ?: continue
        if (old == ReaderState.PROCESSING && event == "succeeded") successes[id] = (successes[id] ?: 0) + 1
        ____2
        states[id] = next
    }
    return states.mapValues { (id, state) -> ReaderSummary(state, successes[id] ?: 0, reconciliations[id] ?: 0) }
}

