data class TransactionFee(val id: String, val feeCents: Long)
data class MerchantFeeReport(val merchant: String, val volumeCents: Long, val feesCents: Long, val netCents: Long)
data class FeeError(val lineNumber: Int, val reason: String)
data class FeeReportWithErrors(val reports: List<MerchantFeeReport>, val errors: List<FeeError>)

private fun percentageFee(amount: Long, basisPoints: Long): Long = (amount * basisPoints + 5_000) / 10_000

fun transactionFees(csv: String): List<TransactionFee> = csv.lineSequence()
    .drop(1).filter { it.isNotBlank() }.map { line ->
        val fields = line.split(',')
        TransactionFee(fields[0], percentageFee(fields[2].toLong(), 290) + 30)
    }.toList()

fun merchantFeeReport(csv: String): List<MerchantFeeReport> = csv.lineSequence()
    .drop(1)
    .filter { it.isNotBlank() }
    .map { it.split(',') }
    .groupBy { it[1] }
    .map { (merchant, rows) ->
        val volume = rows.sumOf { it[2].toLong() }
        val fees = rows.sumOf { percentageFee(it[2].toLong(), 290) + 30 }
        MerchantFeeReport(merchant, volume, fees, volume - fees)
    }
    .sortedWith(compareByDescending<MerchantFeeReport> { it.netCents }.thenBy { it.merchant })

fun merchantFeeReportWithErrors(csv: String): FeeReportWithErrors {
    val totals = mutableMapOf<String, Pair<Long, Long>>()
    val errors = mutableListOf<FeeError>()
    csv.lineSequence().drop(1).forEachIndexed { index, line ->
        if (line.isBlank()) return@forEachIndexed
        val lineNumber = index + 2
        val fields = line.split(',')
        val merchant = fields.getOrNull(1).orEmpty()
        val amount = fields.getOrNull(2)?.toLongOrNull()
        val card = fields.getOrNull(3)?.lowercase()
        when {
            amount == null -> errors += FeeError(lineNumber, "amount is not a number")
            merchant.isBlank() -> errors += FeeError(lineNumber, "missing merchant")
            amount < 0 -> errors += FeeError(lineNumber, "negative amount")
            card != "visa" && card != "amex" -> errors += FeeError(lineNumber, "unknown card")
            else -> {
                val percentage = if (card == "amex") 350L else 290L
                val fee = percentageFee(amount, percentage) + 30
                val old = totals[merchant] ?: (0L to 0L)
                totals[merchant] = (old.first + amount) to (old.second + fee)
            }
        }
    }
    val reports = totals.map { (merchant, values) ->
        MerchantFeeReport(merchant, values.first, values.second, values.first - values.second)
    }.sortedWith(compareByDescending<MerchantFeeReport> { it.netCents }.thenBy { it.merchant })
    return FeeReportWithErrors(reports, errors)
}

