fun ledgerBalances(lines: String): List<Pair<String, Long>> {
    val balances = mutableMapOf<String, Long>()
    lines.lineSequence().filter { it.isNotBlank() }.forEach { line ->
        val fields = line.split(',')
        val merchant = fields[2]
        val amount = fields[3].toLong()
        val delta = if (fields[1] == "charge") amount else -amount
        balances[merchant] = (balances[merchant] ?: 0L) + delta
    }
    return balances.toSortedMap().toList()
}

data class LedgerResult(val balances: List<Pair<String, Long>>, val rejectedLines: List<Int>)

fun ledgerWithRejections(lines: String): LedgerResult {
    val balances = mutableMapOf<String, Long>()
    val rejected = mutableListOf<Int>()
    lines.lineSequence().filter { it.isNotBlank() }.forEachIndexed { index, line ->
        val fields = line.split(',')
        val merchant = fields[2]
        val type = fields[1]
        val amount = fields[3].toLong()
        val current = balances[merchant] ?: 0L
        if (type !in setOf("charge", "refund", "payout") || (type != "charge" && current < amount)) rejected += index + 1
        else balances[merchant] = current + if (type == "charge") amount else -amount
    }
    return LedgerResult(balances.toSortedMap().toList(), rejected)
}

