private data class Entry(val day: Int, val type: String, val merchant: String, val amount: Long, val line: Int)

fun settledLedger(lines: String): LedgerResult {
    val entries = lines.lineSequence().filter { it.isNotBlank() }.mapIndexed { index, line ->
        val fields = line.split(',')
        Entry(fields[0].toInt(), fields[1], fields[2], fields[3].toLong(), index + 1)
    }.toList()
    val balances = mutableMapOf<String, Long>()
    val settledCharges = mutableMapOf<String, Long>()
    val refunds = mutableMapOf<String, Long>()
    val payouts = mutableMapOf<String, Long>()
    val rejected = mutableListOf<Int>()
    entries.forEach { entry ->
        entries.filter { it.type == "charge" && it.merchant == entry.merchant && it.day + 2 <= entry.day }
            .sumOf { it.amount }.also { settledCharges[entry.merchant] = it }
        val balance = balances[entry.merchant] ?: 0L
        when (entry.type) {
            "charge" -> balances[entry.merchant] = balance + entry.amount
            "refund" -> if (balance < entry.amount) rejected += entry.line else {
                balances[entry.merchant] = balance - entry.amount
                refunds[entry.merchant] = (refunds[entry.merchant] ?: 0L) + entry.amount
            }
            "payout" -> {
                val available = (settledCharges[entry.merchant] ?: 0L) -
