fun matchLanguages(header: String, supported: List<String>): List<String> {
    val preferences = header.split(',').mapIndexedNotNull { index, raw ->
        val fields = raw.split(';').map { it.trim() }.filter { it.isNotEmpty() }
        val tag = fields.firstOrNull() ?: return@mapIndexedNotNull null
        val qField = fields.drop(1).firstOrNull { it.startsWith("q=", true) }
        val quality = if (qField == null) 1.0 else qField.substringAfter('=').toDoubleOrNull()
            ?: return@mapIndexedNotNull null
        if (quality !in 0.0..1.0) null else Preference(tag, quality, index)
    }.sortedWith(compareByDescending<Preference> { it.quality }.thenBy { it.order })
    val excluded = preferences.filter { it.quality == 0.0 }.map { it.tag }.toSet()
    val result = mutableListOf<String>()
