private data class CardRule(val start: Int, val end: Int, val length: Int, val brand: String)

private fun parseCardRules(rules: String): List<CardRule> = rules.split(',').map { raw ->
    val parts = raw.split(':')
    val range = parts[0].split('-')
    CardRule(range[0].toInt(), range.last().toInt(), range[0].length, parts[1])
}

fun cardBrand(number: String, rules: String): String {
    val digits = number.trim().filterNot { it == ' ' || it == '-' }
    return parseCardRules(rules).firstOrNull { rule ->
        digits.length >= rule.length && digits.take(rule.length).toIntOrNull()?.let { it in rule.start..rule.end } == true
    }?.brand ?: "UNKNOWN"
}

private fun normalized(number: String): String = number.trim().filterNot { it == ' ' || it == '-' }

private fun brand(digits: String, rules: List<CardRule>): String = rules.firstOrNull { rule ->
    digits.length >= rule.length && digits.take(rule.length).toIntOrNull()?.let { it in rule.start..rule.end } == true
}?.brand ?: "UNKNOWN_BRAND"

private fun luhn(digits: String): Boolean {
    var sum = 0
    var double = false
    for (index in digits.lastIndex downTo 0) {
        var value = digits[index] - '0'
        if (double) { value *= 2; if (value > 9) value -= 9 }
        sum += value
        double = !double
    }
    return sum % 10 == 0
}

fun validateCard(number: String, rules: String): String {
    val digits = normalized(number)
    if (digits.any { it !in '0'..'9' }) return "INVALID_CHARACTERS"
    val cardBrand = brand(digits, parseCardRules(rules))
    if (cardBrand == "UNKNOWN_BRAND") return cardBrand
    val validLength = when (cardBrand) {
        "VISA" -> digits.length in listOf(13, 16, 19)
        "MASTERCARD" -> digits.length == 16
        "AMEX" -> digits.length == 15
        else -> true
    }
    if (!validLength) return "INVALID_LENGTH"
    return if (luhn(digits)) "VALID" else "INVALID_CHECKSUM"
}

