data class Transfer(val from: String, val to: String, val amount: Long)
data class BalanceCheck(val valid: Boolean, val error: String?)

fun balanceTransfers(balances: Map<String, Long>, threshold: Long): List<Transfer> {
    val deficits = balances.filterValues { it < threshold }.map { it.key to threshold - it.value }.toMutableList()
    val surpluses = balances.filterValues { it > threshold }.map { it.key to it.value - threshold }.toMutableList()
    val result = mutableListOf<Transfer>()
    var d = 0
    var s = 0
    while (d < deficits.size && s < surpluses.size) {
        val amount = minOf(deficits[d].second, surpluses[s].second)
        result += Transfer(surpluses[s].first, deficits[d].first, amount)
        deficits[d] = deficits[d].first to deficits[d].second - amount
        surpluses[s] = surpluses[s].first to surpluses[s].second - amount
        if (deficits[d].second == 0L) d++
        if (surpluses[s].second == 0L) s++
    }
    return result
}

fun verify(balances: Map<String, Long>, transfers: List<Transfer>, threshold: Long): BalanceCheck {
    val after = balances.toMutableMap()
    val originalTotal = balances.values.sum()
    transfers.forEach { transfer ->
        if (transfer.amount <= 0) return BalanceCheck(false, "invalid amount")
        val from = after[transfer.from] ?: return BalanceCheck(false, "unknown sender")
        if (from < transfer.amount) return BalanceCheck(false, "insufficient funds")
        if (transfer.to !in after) return BalanceCheck(false, "unknown recipient")
        after[transfer.from] = from - transfer.amount
        after[transfer.to] = after.getValue(transfer.to) + transfer.amount
    }
    return when {
        after.values.any { it < threshold } -> BalanceCheck(false, "below threshold")
        after.values.sum() != originalTotal -> BalanceCheck(false, "total changed")
        else -> BalanceCheck(true, null)
    }
}

fun balanceAccounts(balances: Map<String, Long>, threshold: Long): Result<List<Transfer>> {
    if (balances.values.sum() < threshold * balances.size) return Result.failure(IllegalStateException("error"))
    val transfers = balanceTransfers(balances, threshold)
    val check = verify(balances, transfers, threshold)
    return if (check.valid) Result.success(transfers) else Result.failure(IllegalStateException(check.error ?: "error"))
}

