import java.util.PriorityQueue

data class Lane(val from: String, val to: String, val carrier: String, val cost: Int)

fun parseLanes(text: String): List<Lane> = text.split(",").filter { it.isNotBlank() }.map { raw ->
    val fields = raw.trim().split(":")
    require(fields.size == 4)
    Lane(fields[0], fields[1], fields[2], fields[3].toInt())
}

fun directCost(lanes: List<Lane>, from: String, to: String): Int? =
    lanes.filter { it.from == from && it.to == to }.minOfOrNull { it.cost }

data class Route(val places: List<String>, val carriers: List<String>, val cost: Int)

fun oneStopRoute(lanes: List<Lane>, from: String, to: String): Route? {
    val candidates = lanes.filter { it.from == from }.flatMap { first ->
        lanes.filter { it.from == first.to && it.to == to }.map { second ->
            Route(listOf(from, first.to, to), listOf(first.carrier, second.carrier), first.cost + second.cost)
        }
    }
    return candidates.minByOrNull { it.cost }
}

private data class QueueItem(val cost: Int, val route: Route)

fun cheapestRoute(lanes: List<Lane>, from: String, to: String): Route? {
    if (from == to) return Route(listOf(from), emptyList(), 0)
    val graph = lanes.groupBy { it.from }
    val queue = PriorityQueue<QueueItem>(compareBy { it.cost })
    queue += QueueItem(0, Route(listOf(from), emptyList(), 0))
    val best = mutableMapOf(from to 0)
    while (queue.isNotEmpty()) {
        val current = queue.remove()
        if (current.cost != best[current.route.places.last()]) continue
        if (current.route.places.last() == to) return current.route
        for (lane in graph[current.route.places.last()].orEmpty()) {
            if (lane.to in current.route.places) continue
            val nextCost = current.cost + lane.cost
            if (nextCost < best.getOrDefault(lane.to, Int.MAX_VALUE)) {
                best[lane.to] = nextCost
                queue += QueueItem(nextCost, Route(current.route.places + lane.to, current.route.carriers + lane.carrier, nextCost))
            }
        }
    }
    return null
}

