        result.getOrPut(to) { mutableListOf() } += FxEdge(from, BigDecimal.ONE.divide(rate, 24, RoundingMode.HALF_UP))
    }
    return result
}

private fun money(value: BigDecimal): String = value.setScale(2, RoundingMode.HALF_UP).toPlainString()

