    "TEES20" -> {
        val teeTotal = lines.filter { it.sku == "tee" }.sumOf { it.unitPriceCents * it.quantity }
        (subtotal(lines) - percentDiscount(teeTotal, "0.20")).coerceAtLeast(0)
    }
    else -> throw IllegalArgumentException("unknown coupon")
}

fun checkoutTotal(lines: List<CartLine>, codes: List<String>): Long {
    val normalized = codes.map(String::trim)
