    normalized.filter { it == "SAVE10" }.forEach { total = (total - percentDiscount(total, "0.10")).coerceAtLeast(0) }
    normalized.filter { it == "FIVEOFF" }.forEach { total = (total - 500L).coerceAtLeast(0) }
    return total
}

